    facts: {
      de: ["Auch als Sicherheitsobjekt 21 (S-21) bekannt", "Ehemalige High School"],
      hu: ["S-21-es biztonsági börtönként is ismert", "Egykori középiskola"],
      ro: ["Fost liceu", "Cunoscut ca S-21", "Folosit de Khmerii Roșii", "Acum muzeu al genocidului"],
      en: ["Also known as Security Prison 21 (S-21)", "Former high school"],
      es: ["También conocido como Objeto de Seguridad 21 (S-21)", "Antigua escuela secundaria"],
      pt: ["Também conhecido como Objeto de Segurança 21 (S-21)", "Antiga escola secundária"],
      fr: ["Également connu sous le nom de Bureau de la sécurité 21 (S-21)", "Ancien lycée"],
    }, image: "/poi-images/tuol-sleng-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Tuol-Sleng-Genozid-Museum in Phnom Penh ist eine erschütternde Gedenkstätte für die Opfer des Khmer-Rouge-Regimes. Ursprünglich eine Schule, wurde das Gebäude 1975 in das berüchtigte Sicherheitsgefängnis 21 (S-21) umgewandelt. Unter der Leitung von 'Duch' wurden hier zwischen 12.000 und 20.000 Menschen inhaftiert, gefoltert und anschließend auf den Killing Fields von Choeung Ek hingerichtet. Nur wenige Insassen überlebten diese grausame Einrichtung. Das Museum bewahrt die bedrückende Atmosphäre der Zellen, die Folterinstrumente und tausende von Fotografien der Gefangenen, die bei ihrer Ankunft systematisch registriert wurden. Es dient heute als Ort der Aufklärung und Mahnung, um die Erinnerung an die Verbrechen gegen die Menschlichkeit während der Regierungszeit Pol Pots wachzuhalten. Der Besuch ist eine zutiefst bewegende Erfahrung, die die dunkle Geschichte Kambodschas beleuchtet und die Bedeutung von Gerechtigkeit und Versöhnung betont.",
      hu: "A phnompeni Tuol Szleng Genocídium Múzeum a Vörös Khmer rezsim áldozatainak megrázó emlékhelye. Az eredetileg középiskolaként működő épületegyüttest 1975-ben alakították át a hírhedt 21-es biztonsági börtönné (S-21). 'Duch' vezetése alatt itt 12 000 és 20 000 közötti embert tartottak fogva, kínoztak meg, majd végeztek ki a Choeung Ek-i halálmezőkön. Csak maroknyi fogoly élte túl ezt a kegyetlen intézményt. A múzeum megőrzi a cellák nyomasztó hangulatát, a kínzóeszközöket és a foglyok ezreiről készült fényképeket, akiket érkezésükkor szisztematikusan regisztráltak. Ma az oktatás és az emlékezés helyszíneként szolgál, hogy ébren tartsa a Pol Pot uralma alatt elkövetett emberiség elleni bűncselekmények emlékét. A látogatás mélyen felkavaró élmény, amely rávilágít Kambodzsa sötét történelmére, és hangsúlyozza az igazságszolgáltatás és a megbékélés fontosságát.",
      ro: "Muzeul Genocidului Tuol Sleng din Phnom Penh este un monument zguduitor dedicat victimelor regimului Khmerilor Roșii. Inițial o școală secundară, complexul a fost transformat în 1975 în infama Închisoare de Securitate 21 (S-21). Sub conducerea lui 'Duch', între 12.000 și 20.000 de persoane au fost deținute aici, torturate și ulterior executate pe câmpurile morții de la Choeung Ek. Doar câțiva deținuți au supraviețuit acestei instituții crude. Muzeul păstrează atmosfera deprimantă a celulelor, instrumentele de tortură și mii de fotografii ale prizonierilor care au fost înregistrați sistematic la sosire. Astăzi, servește ca loc de educație și avertizare, pentru a păstra vie memoria crimelor împotriva umanității comise în timpul domniei lui Pol Pot. Vizita este o experiență profund emoționantă care luminează istoria întunecată a Cambodgiei și subliniază importanța justiției și a reconcilierii.",
      en: "The Tuol Sleng Genocide Museum in Phnom Penh is a harrowing memorial to the victims of the Khmer Rouge regime. Originally a secondary school, the complex was transformed in 1975 into the infamous Security Prison 21 (S-21). Under the direction of 'Duch,' between 12,000 and 20,000 people were detained, tortured, and subsequently executed at the Killing Fields of Choeung Ek. Only a handful of inmates survived this cruel institution. The museum preserves the oppressive atmosphere of the cells, the torture instruments, and thousands of photographs of prisoners who were systematically registered upon arrival. Today, it serves as a site for education and remembrance to keep alive the memory of the crimes against humanity committed during Pol Pot's rule. A visit is a deeply moving experience that illuminates Cambodia's dark history and emphasizes the importance of justice and reconciliation.",
      es: "El Museo del Genocidio Tuol Sleng (S-21) en Phnom Penh, Camboya, fue una prisión y centro de tortura durante el régimen de los Jemeres Rojos. Era una antigua escuela convertida en prisión de seguridad en 1975. Se estima que 20.000 prisioneros fueron recluidos aquí antes de ser llevados a Choeung Ek para su ejecución. El museo abrió en 1980. Exhibe instrumentos de tortura, celdas y fotografías de las víctimas. El lugar sirve para recordar los crímenes cometidos por los Jemeres Rojos.",
      pt: "O Museu do Genocídio Tuol Sleng (S-21) em Phnom Penh, Camboja, foi uma prisão e centro de tortura durante o regime do Khmer Vermelho. Era uma antiga escola que foi convertida em prisão de segurança em 1975. Estima-se que 20.000 prisioneiros foram mantidos aqui antes de serem levados para execução em Choeung Ek. O museu foi inaugurado em 1980. Exibe instrumentos de tortura, celas e fotografias das vítimas. O local serve para lembrar os crimes do Khmer Vermelho.",
      fr: "Le musée du génocide de Tuol Sleng (S-21) à Phnom Penh, au Cambodge, était une prison et un centre de torture sous les Khmers rouges. Il s'agissait d'une ancienne école transformée en prison de sécurité en 1975. On estime que 20 000 prisonniers y ont été détenus avant d'être conduits à Choeung Ek pour y être exécutés. Le musée a ouvert ses portes en 1980. Il expose des instruments de torture, des cellules et des photographies des victimes. Le site sert de lieu de mémoire pour les crimes commis par les Khmers rouges.",
    },
    factsAdvanced: {
      de: ["War ursprünglich die Tuol Svay Pray High School.", "Wurde am 7. Januar 1979 von vietnamesischen Truppen entdeckt.", "Das Museum wurde bereits 1980 offiziell eröffnet.", "Beherbergt das UNESCO-Weltdokumentenerbe der S-21-Archive.", "Weniger als 15 Überlebende sind namentlich bekannt.", "Besteht aus vier Hauptgebäuden (Block A, B, C und D)."],
      hu: ["Eredetileg a Tuol Svay Pray középiskola volt.", "1979. január 7-én fedezték fel a vietnámi csapatok.", "A múzeumot már 1980-ban hivatalosan megnyitották.", "Itt őrzik az S-21 archívumát, amely az UNESCO Világemlékezet listáján szerepel.", "Kevesebb mint 15 túlélőt ismernek név szerint.", "Négy fő épületből áll (A, B, C és D blokk)."],
      ro: ["Inițial a fost Liceul Tuol Svay Pray.", "Descoperit de trupele vietnameze pe 7 ianuarie 1979.", "Muzeul a fost deschis oficial încă din anul 1980.", "Găzduiește arhivele S-21, incluse în registrul Memoria Lumii al UNESCO.", "Mai puțin de 15 supraviețuitori sunt cunoscuți pe nume.", "Format din patru clădiri principale (Blocurile A, B, C și D)."],
      en: ["Originally the Tuol Svay Pray High School.", "Discovered by Vietnamese troops on January 7, 1979.", "The museum was officially opened as early as 1980.", "Houses the S-21 archives, included in the UNESCO Memory of the World register.", "Fewer than 15 survivors are known by name.", "Consists of four main buildings (Blocks A, B, C, and D)."],
      es: ["Origen: Escuela", "Conversión en prisión: 1975", "Víctimas estimadas: 20.000", "Apertura del museo: 1980", "Ubicación: Phnom Penh", "Condena de Duch: 2009"],
      pt: ["Origem: Escola", "Conversão em prisão: 1975", "Vítimas estimadas: 20.000", "Abertura do museu: 1980", "Localização: Phnom Penh", "Condenação de Duch: 2009"],
      fr: ["Origine : École", "Transformation en prison : 1975", "Nombre estimé de victimes : 20 000", "Ouverture du musée : 1980", "Lieu : Phnom Penh", "Condamnation de Duch : 2009"],
    },
